pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Set up an admin to create a game item and mint tokens
        // address(this) is already admin in constructor
        // Create a game item (tokenId 0) with price 0, dailyAllowance 0, finiteSupply false, transferable true
        c.createGameItem("item", "ipfs://uri", false, true, 0, 0, 0);
        // Mint 1 token of id 0 to address(this)
        c.mint(0, 1);
        // Now balanceOf(address(this), 0) should return 1 in reference, 0 in bug
        uint256 balance = c.balanceOf(address(this), 0);
        assertTrue(balance == 1, "balance should be 1");
    }
}

