pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // 1. Set up state: create a game item (tokenId 0) and mint one token to address(1)
        vm.prank(address(this));
        c.createGameItem("Item", "uri", false, true, 100, 1 ether, 10);
        // Mint one token of id 0 to address(1)
        vm.prank(address(this));
        c.setAllowedBurningAddresses(address(this));
        vm.prank(address(this));
        c.mint(0, 1);
        // Transfer the minted token to address(1) via safeTransferFrom (since we are owner of the token)
        vm.prank(address(this));
        c.safeTransferFrom(address(this), address(1), 0, 1, "");

        // 2. Call balanceOfBatch with accounts [address(1), address(2)] and ids [0, 0]
        address[] memory accounts = new address[](2);
        accounts[0] = address(1);
        accounts[1] = address(2);
        uint256[] memory ids = new uint256[](2);
        ids[0] = 0;
        ids[1] = 0;
        uint256[] memory balances = c.balanceOfBatch(accounts, ids);

        // 3. Assert: reference returns balances[0] = 1, bug returns balances[0] = 0
        assertTrue(balances[0] == 1, "First balance should be 1 (reference) but got something else");
    }
}

