        uint256[] memory balances = c.balanceOfBatch(accounts, ids);
        // In the reference, balanceOf(address(this), 0) returns 1 (minted by constructor)
        // In the bug, it always returns 0
        assertTrue(balances[0] == 1);
    }
}
